const ORIGINAL_SOURCES: Record<string, string> = {
  "lib/engine/posture-context.ts": "import type { EnginePosture } from './types';\n\n/** One short sentence per posture: definition only. No banner disclaimers duplicated here. */\nexport const ENGINE_POSTURE_CONTEXT: Record<EnginePosture, string> = {\n  normal:\n    'Within expected range. Most of your balance stays steady, with conservative yield and reserve capacity kept visible.',\n  tightening:\n    'Protective posture is increasing. Reserve targets are more prominent while conditions are reviewed.',\n  tightened:\n    'Protective posture is elevated. Reserve targets stay prioritized until conditions ease.',\n  recovery:\n    'Within expected range. Targets are easing toward a steadier posture while reserve discipline remains visible.',\n};\n",
  "lib/engine/notices.ts": "import type { EngineNotice, EnginePosture } from './types';\n\nexport type NonNormalEnginePosture = Exclude<EnginePosture, 'normal'>;\n\nexport const ENGINE_NOTICE_COPY: Record<NonNormalEnginePosture, EngineNotice> = {\n  tightening: {\n    title: 'Stability protection is tightening',\n    body: 'The system is moving toward a more protective mix while conditions are reviewed. When protection and the reserve take priority, the conservative yield target can be lower. This is informational guidance about system intent. It is not your ledger balance, holdings, or confirmed positions.',\n  },\n  tightened: {\n    title: 'Stability protection is elevated',\n    body: 'The system is holding a more protective mix with the reserve prioritized while conditions stay elevated. This is informational guidance about system intent. It is not your ledger balance, holdings, or confirmed positions.',\n  },\n  recovery: {\n    title: 'Stability protection is easing',\n    body: 'The system is moving toward steadier targets as conditions stabilize, with reserve discipline still in view. This is informational guidance about system intent. It is not your ledger balance, holdings, or confirmed positions.',\n  },\n};\n",
  "app/(app)/dashboard/EnginePostureHeader.tsx": "\"use client\";\n\nimport finish from '../product-finish.module.css';\n\nimport React from \"react\";\nimport { usePathname, useSearchParams } from \"next/navigation\";\nimport { ENGINE_POSTURE_CONTEXT } from \"../../../lib/engine/posture-context\";\nimport type { EnginePosture, EngineState } from \"../../../lib/engine/types\";\nimport { ENGINE_ILLUSTRATIVE_VALUES_LABEL } from \"../../../lib/engine/stability-review-snapshot-copy\";\nimport { formatShortDate } from \"../../../lib/state/last-visit\";\nimport {\n  CLASS_A_VAL_002_DASHBOARD_PATH,\n  CLASS_A_VAL_002_JOURNEY_PARAM,\n  CLASS_A_VAL_002_JOURNEY_VALUE,\n  isSyntheticJourneyPrimaryCondition,\n} from \"../../../lib/state/synthetic-journey\";\n\nconst BADGE_LABELS: Record<EnginePosture, string> = {\n  normal: \"NORMAL\",\n  tightening: \"TIGHTENING\",\n  tightened: \"TIGHTENED\",\n  recovery: \"RECOVERY\",\n};\n\nconst BADGE_TONES: Record<EnginePosture, string> = {\n  normal: \"border-hedgr-200 bg-hedgr-100 text-hedgr-800\",\n  tightening: \"border-hedgr-300 bg-white text-hedgr-dark\",\n  tightened: \"border-hedgr-primary bg-white text-hedgr-800\",\n  recovery: \"border-hedgr-200 bg-white text-hedgr-600\",\n};\n\nconst SIMULATION_ATTENTION_ANSWERS: Record<EnginePosture, string> = {\n  normal: \"No other change stands out in the information shown.\",\n  tightening: \"A change in the guidance needs review.\",\n  tightened: \"A change in the guidance needs review.\",\n  recovery: \"A change in the guidance needs review.\",\n};\n\nconst SIMULATION_STATUS_CONTEXT: Record<EnginePosture, string> = {\n  normal:\n    \"The completed simulated changes reconcile with the current position.\",\n  tightening:\n    \"Hedgr's qualitative reading shows stability guidance becoming more cautious.\",\n  tightened:\n    \"Hedgr's qualitative reading shows stability guidance in a more cautious state.\",\n  recovery:\n    \"Hedgr's qualitative reading shows stability guidance easing from a more cautious state.\",\n};\n\ntype ComparisonState = \"empty\" | \"first-event\" | \"change\";\n\nconst SIMULATION_COMPARISON_CONTEXT: Record<ComparisonState, string> = {\n  empty:\n    \"Nothing to compare yet. A first completed simulated event will create a starting point.\",\n  \"first-event\":\n    \"A first simulated position is now visible. There is no earlier position to compare yet.\",\n  change: SIMULATION_STATUS_CONTEXT.normal,\n};\n\nconst RESEARCH_STARTING_POINT_CONTEXT = {\n  empty: \"Nothing to compare yet. Your first completed simulated event will establish a starting point.\",\n  \"first-event\": \"Your first simulated position is now visible. This is your starting point.\",\n};\n\nconst SIMULATION_COMPARISON_ATTENTION: Record<ComparisonState, string> = {\n  empty: \"There is not enough information to compare yet.\",\n  \"first-event\": \"There is no earlier position to compare yet.\",\n  change: SIMULATION_ATTENTION_ANSWERS.normal,\n};\n\ntype EnginePostureHeaderProps = {\n  engineState: EngineState;\n  syntheticJourneyActive?: boolean;\n  comparisonState?: ComparisonState;\n  latestChangeType?: \"DEPOSIT\" | \"WITHDRAW\";\n  latestChangeAmountUSD?: number;\n  latestChangeCreatedAt?: number;\n  homeDate?: number | null;\n  changeIncludedInBalance?: boolean;\n  currencyContextVisible?: boolean;\n  redesigned?: boolean;\n};\n\nexport function EnginePostureHeader({\n  engineState,\n  syntheticJourneyActive = false,\n  comparisonState = \"change\",\n  latestChangeType,\n  latestChangeAmountUSD,\n  latestChangeCreatedAt,\n  homeDate,\n  changeIncludedInBalance = true,\n  currencyContextVisible = false,\n  redesigned = false,\n}: EnginePostureHeaderProps) {\n  const { posture, notice } = engineState;\n  const pathname = usePathname();\n  const searchParams = useSearchParams();\n  // The presentation prop also serves default Home; simplify only explicit research.\n  const researchStartingPoint =\n    syntheticJourneyActive &&\n    posture === \"normal\" &&\n    comparisonState !== \"change\" &&\n    isSyntheticJourneyPrimaryCondition(searchParams?.toString(), pathname) &&\n    (pathname === CLASS_A_VAL_002_DASHBOARD_PATH ||\n      searchParams?.get(CLASS_A_VAL_002_JOURNEY_PARAM) === CLASS_A_VAL_002_JOURNEY_VALUE);\n  const showNotice = posture !== \"normal\" && Boolean(notice);\n  const scopeAttentionToActivity = currencyContextVisible && syntheticJourneyActive &&\n    posture === \"normal\" && comparisonState === \"change\" &&\n    isSyntheticJourneyPrimaryCondition(searchParams?.toString(), pathname) &&\n    (pathname === CLASS_A_VAL_002_DASHBOARD_PATH ||\n      searchParams?.get(CLASS_A_VAL_002_JOURNEY_PARAM) === CLASS_A_VAL_002_JOURNEY_VALUE);\n  const researchRedesign = redesigned && syntheticJourneyActive && isSyntheticJourneyPrimaryCondition(searchParams?.toString(), pathname) && (pathname === CLASS_A_VAL_002_DASHBOARD_PATH || searchParams?.get(CLASS_A_VAL_002_JOURNEY_PARAM) === CLASS_A_VAL_002_JOURNEY_VALUE);\n  const waitingForFirstEvent = researchRedesign && posture === \"normal\" && comparisonState === \"empty\";\n  const preEventCaution = researchRedesign && posture !== \"normal\" && comparisonState === \"empty\";\n  const completedChangeCard = researchRedesign && posture === \"normal\" && comparisonState === \"change\";\n  const completedChangeIncluded = completedChangeCard && changeIncludedInBalance &&\n    latestChangeType !== undefined && latestChangeAmountUSD !== undefined;\n  const Heading = completedChangeCard ? \"h2\" : \"p\";\n  const eventDate = latestChangeCreatedAt !== undefined && Number.isFinite(latestChangeCreatedAt)\n    ? new Date(latestChangeCreatedAt) : null;\n  const eventDateSuffix = eventDate\n    ? homeDate != null && eventDate.toDateString() === new Date(homeDate).toDateString()\n      ? \" today\" : ` on ${formatShortDate(latestChangeCreatedAt!)}`\n    : \"\";\n  const changeObservation =\n    latestChangeType && latestChangeAmountUSD !== undefined\n      ? researchRedesign ? <>A simulated {latestChangeType === \"WITHDRAW\" ? \"withdrawal\" : \"deposit\"}{eventDateSuffix}.</> : `The simulated ${\n          latestChangeType === \"WITHDRAW\" ? \"expense\" : \"deposit\"\n        } explains why the current position is $${latestChangeAmountUSD.toFixed(\n          2\n        )} ${latestChangeType === \"WITHDRAW\" ? \"lower\" : \"higher\"}.`\n      : SIMULATION_COMPARISON_CONTEXT.change;\n\n  if (\n    posture !== \"normal\" &&\n    !notice &&\n    process.env.NODE_ENV !== \"production\"\n  ) {\n    console.warn(\n      `[EnginePostureHeader] Missing EngineState.notice for posture \"${posture}\"`\n    );\n  }\n\n  return (\n    <header\n      className={`space-y-3 ${finish.observationHeader}`}\n      aria-labelledby=\"dashboard-current-status-label\"\n      data-testid=\"dashboard-current-status\"\n      role={completedChangeCard ? \"region\" : undefined}\n    >\n      <div className=\"space-y-2\">\n        <div className=\"space-y-1\">\n          <Heading\n            id=\"dashboard-current-status-label\"\n            className={researchRedesign ? \"text-sm font-semibold text-hedgr-800\" : \"text-[11px] font-bold uppercase tracking-[0.14em] text-hedgr-600\"}\n          >\n            {waitingForFirstEvent\n              ? \"Start with a simulated deposit\"\n              : preEventCaution\n                ? \"Current status\"\n                : researchRedesign && posture === \"normal\" && comparisonState === \"change\"\n                  ? \"What changed\"\n                  : syntheticJourneyActive ? \"What Hedgr notices\" : \"Current status\"}\n          </Heading>\n        </div>\n        {!syntheticJourneyActive || posture !== \"normal\" ? (\n          <p className=\"text-xs leading-relaxed text-hedgr-500\">\n            {ENGINE_ILLUSTRATIVE_VALUES_LABEL}\n          </p>\n        ) : null}\n        {!syntheticJourneyActive ? (\n          <span\n            data-testid=\"engine-posture-badge\"\n            data-posture={posture}\n            className={`inline-flex items-center rounded-full border px-3 py-1 text-[11px] font-semibold tracking-wide ${BADGE_TONES[posture]}`}\n          >\n            {BADGE_LABELS[posture]}\n          </span>\n        ) : null}\n      </div>\n\n      <p\n        className=\"max-w-xl text-sm leading-relaxed text-hedgr-dark\"\n        data-testid=\"engine-posture-context\"\n      >\n        {waitingForFirstEvent\n          ? \"Nothing to compare yet. Add a simulated deposit when you’re ready — this is practice money only.\"\n          : syntheticJourneyActive\n          ? posture === \"normal\"\n            ? comparisonState === \"change\"\n              ? changeObservation\n              : researchStartingPoint\n                ? RESEARCH_STARTING_POINT_CONTEXT[comparisonState]\n                : SIMULATION_COMPARISON_CONTEXT[comparisonState]\n            : SIMULATION_STATUS_CONTEXT[posture]\n          : ENGINE_POSTURE_CONTEXT[posture]}\n      </p>\n\n      {syntheticJourneyActive && !waitingForFirstEvent ? (\n        <div className={`space-y-2 ${finish.attention}`}>\n          {completedChangeIncluded ? (\n            <p className=\"text-sm leading-relaxed text-hedgr-dark\">\n              This simulated {latestChangeType === \"WITHDRAW\" ? \"withdrawal\" : \"deposit\"} is included in the balance above.\n            </p>\n          ) : null}\n          {!researchStartingPoint && !(researchRedesign && posture === \"normal\") ? (\n            <>\n              <h2 className=\"text-sm font-semibold tracking-tight text-hedgr-800\">\n                Does anything need attention?\n              </h2>\n              <p\n                data-testid=\"engine-simulation-attention-answer\"\n                className=\"text-sm font-semibold leading-relaxed text-hedgr-800\"\n              >\n                {posture === \"normal\"\n                  ? scopeAttentionToActivity\n                    ? \"No other change stands out in the simulated activity.\"\n                    : SIMULATION_COMPARISON_ATTENTION[comparisonState]\n                  : SIMULATION_ATTENTION_ANSWERS[posture]}\n              </p>\n            </>\n          ) : null}\n          <p className=\"text-xs leading-relaxed text-hedgr-500\">\n            {isSyntheticJourneyPrimaryCondition(searchParams?.toString(), pathname) &&\n            (pathname === CLASS_A_VAL_002_DASHBOARD_PATH ||\n              searchParams?.get(CLASS_A_VAL_002_JOURNEY_PARAM) === CLASS_A_VAL_002_JOURNEY_VALUE)\n              ? \"This is what happened in your simulation. It doesn’t tell you what will happen next.\"\n              : \"This is what happened in the example. It doesn’t tell you what will happen next.\"}\n          </p>\n        </div>\n      ) : null}\n\n      {!syntheticJourneyActive ? (\n        <p\n          className=\"text-sm font-medium text-hedgr-600\"\n          data-testid=\"engine-posture-action-guidance\"\n        >\n          There is nothing here you need to manage.\n        </p>\n      ) : null}\n\n      {showNotice ? (\n        <div\n          data-testid=\"engine-posture-banner\"\n          role=\"status\"\n          className=\"rounded-2xl border border-hedgr-100 bg-white px-4 py-3.5 text-sm leading-snug text-hedgr-800 shadow-sm\"\n        >\n          <p className=\"font-semibold text-hedgr-800\">{notice?.title}</p>\n          <p className=\"mt-2 text-hedgr-dark\">{notice?.body}</p>\n        </div>\n      ) : null}\n    </header>\n  );\n}\n",
  "app/(app)/dashboard/page.tsx": "\"use client\";\n\nimport { getSimulationDisplayRate, useSimulationDisplayCurrency } from \"../../../lib/state/simulation-display-currency\";\nimport finish from '../product-finish.module.css';\nimport home from './synthetic-home.module.css';\nimport { SimulationDisplayCurrencySelector } from '../../../components/SimulationDisplayCurrencySelector';\n\nimport Link from \"next/link\";\nimport { usePathname, useSearchParams } from \"next/navigation\";\nimport { useEffect, useMemo, useRef, useState } from \"react\";\nimport { EngineAllocationBands } from \"./EngineAllocationBands\";\nimport { EnginePostureHeader } from \"./EnginePostureHeader\";\nimport { countChanges } from \"./lineLabels\";\nimport { PositionLine } from \"./PositionLine\";\nimport { DanielExampleHome } from './DanielExampleHome';\nimport { SarahExampleHome } from './SarahExampleHome';\nimport { HomeHero } from './HomeHero';\nimport { RateLine } from './RateLine';\nimport { CurrencyInsight } from \"./CurrencyInsight\";\nimport { EngineProtectiveGuidance } from \"./EngineProtectiveGuidance\";\nimport { EngineStabilityExplainer } from \"./EngineStabilityExplainer\";\nimport { EngineStabilityReviewSnapshot } from \"./EngineStabilityReviewSnapshot\";\nimport { useBalance } from \"../../../lib/hooks/useBalance\";\nimport { defiAdapter } from \"../../../lib/defi\";\nimport { useLedgerStore } from \"../../../lib/state/ledger\";\nimport { EmptyState, ErrorState } from \"@hedgr/ui\";\nimport {\n  BalanceWithLocalEstimate,\n  PolicyDisclosure,\n} from \"../../../components\";\nimport { useEngineState } from \"../../../lib/engine/useEngineState\";\nimport { ENGINE_ILLUSTRATIVE_VALUES_LABEL } from \"../../../lib/engine/stability-review-snapshot-copy\";\nimport { usePolicy } from \"../../../lib/policy/usePolicy\";\nimport { getEnvironmentMode } from \"../../../lib/env/mode\";\nimport {\n  buildPositionEntries,\n  clearLastVisit,\n  formatChangeCount,\n  formatDateLine,\n  formatShortDate,\n  formatUsd,\n  readLastVisit,\n  summariseSinceLastVisit,\n  writeLastVisit,\n} from \"../../../lib/state/last-visit\";\nimport {\n  PublicTxStatus,\n  txToLifecycle,\n  type TxLifecycle,\n} from \"../../../lib/tx\";\nimport {\n  CLASS_A_VAL_002_DANIEL_EXAMPLE,\n  CLASS_A_VAL_002_SARAH_EXAMPLE,\n  CLASS_A_VAL_002_DASHBOARD_PATH,\n  CLASS_A_VAL_002_EXAMPLE_PARAM,\n  CLASS_A_VAL_002_JOURNEY_PARAM,\n  CLASS_A_VAL_002_RESET_PARAM,\n  CLASS_A_VAL_002_JOURNEY_VALUE,\n  SYNTHETIC_JOURNEY_EXAMPLES,\n  getSyntheticJourneyHref,\n  isSyntheticJourneyPrimaryCondition,\n  isSyntheticJourneyResetRequested,\n  parseSyntheticJourneyExample,\n} from \"../../../lib/state/synthetic-journey\";\nimport { DANIEL_HOME_READ, DANIEL_HOME_TIMELINE } from \"../../../lib/state/daniel-home-fixture\";\nimport { SARAH_HOME_READ } from \"../../../lib/state/sarah-home-fixture\";\n\nfunction formatActivityDayLabel(timestamp: number): string {\n  const date = new Date(timestamp);\n  const today = new Date();\n  const yesterday = new Date(today);\n  yesterday.setDate(yesterday.getDate() - 1);\n\n  if (date.toDateString() === today.toDateString()) {\n    return \"Today\";\n  }\n  if (date.toDateString() === yesterday.toDateString()) {\n    return \"Yesterday\";\n  }\n  return date.toLocaleDateString(\"en-US\", { month: \"short\", day: \"numeric\" });\n}\n\nfunction activityTitle(\n  tx: TxLifecycle,\n  syntheticJourneyActive: boolean\n): string {\n  const title = tx.type === \"DEPOSIT\" ? \"Deposit\" : \"Withdrawal\";\n  return syntheticJourneyActive ? `Simulated ${title.toLowerCase()}` : title;\n}\n\ntype SyntheticComparisonState = \"empty\" | \"first-event\" | \"change\";\n\n// HOME-EXPERIENCE-001 T5: one restrained arrival motion after a confirmed change.\nconst ARRIVAL_SETTLE_MS = 600;\n\nfunction motionAllowed(): boolean {\n  if (typeof window === \"undefined\" || typeof window.requestAnimationFrame !== \"function\") return false;\n  try {\n    return typeof window.matchMedia === \"function\" &&\n      !window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n  } catch {\n    return false;\n  }\n}\n\n// Retired wallet balance mode (§344) left this key in some browsers. Nothing reads\n// it; a journey reset removes it so no stale balance outlives the clean start.\nfunction removeRetiredWalletBalance(): void {\n  try {\n    window.localStorage.removeItem(\"hedgr:wallet\");\n  } catch {\n    // no-op\n  }\n}\n\nexport default function DashboardPage() {\n  const { total, available, pending, asOf, isLoading, error, currency, refresh } =\n    useBalance();\n  const engineState = useEngineState();\n  const { isFeatureEnabled } = usePolicy();\n  const transactions = useLedgerStore((s) => s.transactions);\n  const clearTransactions = useLedgerStore((s) => s.clear);\n  const [apy, setApy] = useState<number | null>(null);\n  const [apyError, setApyError] = useState<string | null>(null);\n  const [ready, setReady] = useState(false);\n  const pathname = usePathname();\n  const searchParams = useSearchParams();\n  const syntheticJourneyEligible = isSyntheticJourneyPrimaryCondition(\n    searchParams?.toString(),\n    pathname\n  );\n  const syntheticJourneyActive =\n    syntheticJourneyEligible &&\n    (pathname === CLASS_A_VAL_002_DASHBOARD_PATH ||\n      searchParams?.get(CLASS_A_VAL_002_JOURNEY_PARAM) ===\n        CLASS_A_VAL_002_JOURNEY_VALUE);\n  // §362: Daniel's reserve shows only on the journey Home, selected only by the URL.\n  const selectedExample = parseSyntheticJourneyExample(searchParams?.toString());\n  const danielExample =\n    syntheticJourneyActive && selectedExample === CLASS_A_VAL_002_DANIEL_EXAMPLE;\n  const sarahExample =\n    syntheticJourneyActive && selectedExample === CLASS_A_VAL_002_SARAH_EXAMPLE;\n  const exampleActive = danielExample || sarahExample;\n  const displayCurrency = useSimulationDisplayCurrency(syntheticJourneyActive && !exampleActive);\n  const simulatedEnvironment = getEnvironmentMode() !== \"live\";\n  const productSimulationActive =\n    syntheticJourneyActive || simulatedEnvironment;\n  const explicitSyntheticJourney =\n    syntheticJourneyActive;\n  const cleanStartRequested = isSyntheticJourneyResetRequested(\n    searchParams?.toString()\n  );\n\n  useEffect(() => {\n    defiAdapter\n      .getNetApy()\n      .then(setApy)\n      .catch(() => setApyError(\"Unable to load example yield\"));\n  }, []);\n\n  useEffect(() => {\n    if (cleanStartRequested || (sarahExample && searchParams?.has(CLASS_A_VAL_002_RESET_PARAM))) {\n      // §374: eligible Sarah consumes reset while refusing all simulation writes.\n      if (!sarahExample) {\n        clearTransactions();\n        removeRetiredWalletBalance();\n      }\n      const resetParams = new URLSearchParams(searchParams?.toString());\n      resetParams.delete(CLASS_A_VAL_002_RESET_PARAM);\n      const resetTarget = syntheticJourneyActive && selectedExample !== \"own\"\n        ? `${pathname}?${resetParams.toString()}`\n        : CLASS_A_VAL_002_DASHBOARD_PATH;\n      window.history.replaceState(\n        window.history.state,\n        \"\",\n        resetTarget\n      );\n    }\n    setReady(true);\n  }, [cleanStartRequested, clearTransactions, pathname, searchParams, selectedExample, syntheticJourneyActive, sarahExample]);\n\n  // HOME-EXPERIENCE-001 T3: read the previous Home visit once, then record this one.\n  // A journey reset only clears the value; the next ordinary Home visit records it.\n  const [previousVisit, setPreviousVisit] = useState<number | null>(null);\n  const [visitRead, setVisitRead] = useState(false);\n  const [today, setToday] = useState<number | null>(null);\n  const visitRecorded = useRef(false);\n  // §362: an example never records a visit; arriving on one and returning records none either.\n  const arrivedOnExample = useRef(exampleActive);\n  useEffect(() => {\n    if (exampleActive) {\n      if (danielExample) setToday((current) => current ?? Date.now());\n      return;\n    }\n    if (!productSimulationActive || visitRecorded.current) return;\n    visitRecorded.current = true;\n    const now = Date.now();\n    if (cleanStartRequested) {\n      clearLastVisit();\n      setPreviousVisit(null);\n    } else {\n      setPreviousVisit(readLastVisit());\n      if (!arrivedOnExample.current) writeLastVisit(now);\n    }\n    setToday(now);\n    setVisitRead(true);\n  }, [productSimulationActive, cleanStartRequested, exampleActive, danielExample]);\n\n  const hasNoTransactions = transactions.length === 0;\n  const isFirstTimeUser =\n    ready && hasNoTransactions && available === 0 && !isLoading;\n  const hasSyntheticFixtureState =\n    ready && !isLoading && (!hasNoTransactions || available !== 0);\n\n  const restartSyntheticJourney = () => {\n    if (!syntheticJourneyActive) return;\n\n    const confirmed = window.confirm(\n      \"Restart the simulated journey? This clears only the simulated balance and Activity stored on this device. No real money or external records are affected.\"\n    );\n    if (!confirmed) return;\n\n    clearTransactions();\n    removeRetiredWalletBalance();\n    clearLastVisit();\n    setPreviousVisit(null);\n  };\n\n  const recentActivity = useMemo(() => {\n    const sorted = [...transactions].sort(\n      (a, b) => b.created_at - a.created_at\n    );\n    return sorted.slice(0, 3).map(txToLifecycle);\n  }, [transactions]);\n\n  const completedSyntheticActivity = useMemo(\n    () =>\n      transactions\n        .map(txToLifecycle)\n        .filter((tx) => tx.status === PublicTxStatus.SUCCESS)\n        .sort((a, b) => a.createdAt - b.createdAt || a.id.localeCompare(b.id)),\n    [transactions]\n  );\n\n  const syntheticComparison = useMemo(() => {\n    const completedCount = completedSyntheticActivity.length;\n    const comparisonState: SyntheticComparisonState =\n      completedCount === 0\n        ? \"empty\"\n        : completedCount === 1\n        ? \"first-event\"\n        : \"change\";\n    const lastEvent = completedSyntheticActivity.at(-1);\n\n    return {\n      comparisonState,\n      lastEvent,\n    };\n  }, [completedSyntheticActivity]);\n\n  // Wait for the existing balance projection and preference hydration. After reset,\n  // the ledger can be empty one render before useBalance publishes the cleared total.\n  const currencyContextVisible = syntheticJourneyActive && ready && asOf > 0 &&\n    !isLoading && !error &&\n    (!cleanStartRequested || (hasNoTransactions && total === 0)) &&\n    !(hasNoTransactions && Number.isFinite(total) && total > 0);\n  const currencyComparisonPending = pending !== 0 || total !== available ||\n    transactions.some((tx) => tx.status === \"pending\");\n\n  // T3 surfaces derive only from completed ledger entries (Activity order). They\n  // appear only when that derivation agrees with the displayed balance; otherwise\n  // Home keeps the existing observation.\n  const positionEntries = useMemo(\n    () => buildPositionEntries(transactions.map(txToLifecycle)),\n    [transactions]\n  );\n  const positionLoading = productSimulationActive && (!ready || asOf === 0 || isLoading);\n  const ledgerPosition = positionEntries.at(-1)?.balanceAfter ?? 0;\n  const positionDerivable =\n    productSimulationActive && ready && visitRead && !positionLoading && !error &&\n    (!cleanStartRequested || (hasNoTransactions && total === 0)) &&\n    !currencyComparisonPending && Math.abs(ledgerPosition - total) < 0.005;\n  const normalPosture = engineState.posture === \"normal\";\n  const firstUse = positionDerivable && transactions.length === 0;\n  const sinceSummary =\n    positionDerivable && previousVisit !== null && positionEntries.length > 0\n      ? summariseSinceLastVisit(positionEntries, previousVisit)\n      : null;\n  // HOME-DEDUP-001 (§328 decision 3): while the observation explains one or several changes,\n  // default-route Recent activity would repeat those entries, so it is hidden.\n  const sinceChangesShown =\n    normalPosture && !positionLoading && sinceSummary !== null && sinceSummary.kind !== \"no-change\";\n  const sinceDelta =\n    sinceSummary && sinceSummary.kind !== \"no-change\"\n      ? +(sinceSummary.to - sinceSummary.from).toFixed(2)\n      : 0;\n  // Only the journey names its display currency explicitly; default Home omits the line.\n  const estimateCurrency = syntheticJourneyActive ? displayCurrency : null;\n\n  // T5 arrival: count from the last figure seen and settle the line.\n  // Runs once per Home arrival, only for a confirmed change; reduced motion shows the end state.\n  const arrivalChange =\n    sinceSummary && normalPosture && sinceSummary.kind !== \"no-change\" && sinceDelta !== 0\n      ? sinceSummary\n      : null;\n  const arrivalKey = arrivalChange ? `${arrivalChange.from}:${arrivalChange.to}` : \"\";\n  const [arrivalPhase, setArrivalPhase] = useState<\"idle\" | \"running\" | \"done\">(\"idle\");\n  const [arrivalProgress, setArrivalProgress] = useState(0);\n  const [arrivalAnnouncement, setArrivalAnnouncement] = useState(\"\");\n  const arrivalStarted = useRef(false);\n  useEffect(() => {\n    if (!arrivalKey || !arrivalChange || arrivalStarted.current) return;\n    arrivalStarted.current = true;\n    const change = +(arrivalChange.to - arrivalChange.from).toFixed(2);\n    const sentence = syntheticJourneyActive\n      ? `Your simulated balance is now ${formatUsd(arrivalChange.to)}. On your last visit it was ${formatUsd(arrivalChange.from)}.`\n      : `Your position is now ${formatUsd(arrivalChange.to)}, ${formatUsd(change)} ${change > 0 ? \"higher\" : \"lower\"} than on your last visit.`;\n    const finish = () => {\n      setArrivalProgress(1);\n      setArrivalPhase(\"done\");\n      setArrivalAnnouncement(sentence);\n    };\n    if (!motionAllowed()) {\n      finish();\n      return;\n    }\n    setArrivalPhase(\"running\");\n    let frame = 0;\n    const start = performance.now();\n    const tick = (now: number) => {\n      const t = Math.min(1, (now - start) / ARRIVAL_SETTLE_MS);\n      setArrivalProgress(1 - Math.pow(1 - t, 3));\n      if (t < 1) frame = window.requestAnimationFrame(tick);\n      else finish();\n    };\n    frame = window.requestAnimationFrame(tick);\n    return () => {\n      window.cancelAnimationFrame(frame);\n      finish();\n    };\n    // arrivalKey captures the only inputs that matter; the summary object is rebuilt each render.\n  }, [arrivalKey, syntheticJourneyActive]);\n  // Before the first frame, show the last-seen figure only when motion will actually run.\n  const arrivalAnimating =\n    arrivalChange !== null && arrivalPhase !== \"done\" && (arrivalPhase === \"running\" || motionAllowed());\n  const arrivalSettle = arrivalAnimating ? arrivalProgress : 1;\n  const displayedTotal = arrivalAnimating && arrivalChange\n    ? +(arrivalChange.from + (arrivalChange.to - arrivalChange.from) * arrivalProgress).toFixed(2)\n    : total;\n  const trustHref = syntheticJourneyActive\n    ? `/settings/trust?${CLASS_A_VAL_002_JOURNEY_PARAM}=${CLASS_A_VAL_002_JOURNEY_VALUE}`\n    : \"/settings/trust\";\n  const openSimulationExplainer = () => {\n    const details = document.querySelector<HTMLDetailsElement>(\n      '[data-testid=\"simulation-technical-details\"]'\n    );\n    if (!details) {\n      window.location.assign(trustHref);\n      return;\n    }\n    details.open = true;\n    details.querySelector(\"summary\")?.focus();\n    details.scrollIntoView({ block: \"nearest\" });\n  };\n\n  const journeyActivityIncluded = syntheticJourneyActive && normalPosture && positionDerivable &&\n    (sinceSummary\n      ? sinceSummary.kind !== \"no-change\"\n      : syntheticComparison.comparisonState === \"change\" && syntheticComparison.lastEvent !== undefined);\n\n  const balanceHeroTail = <>\n      {productSimulationActive ? (\n        <p className=\"sr-only\" role=\"status\" data-testid=\"dashboard-arrival-announcement\">\n          {arrivalAnnouncement}\n        </p>\n      ) : null}\n      {positionLoading ? (\n        <p className={home.balanceCaption} data-testid=\"dashboard-synthetic-balance-explainer\">Loading your position…</p>\n      ) : firstUse ? (\n        <p className={home.balanceCaption} data-testid=\"dashboard-synthetic-balance-explainer\">No simulated activity yet.</p>\n      ) : syntheticJourneyActive ? (\n        journeyActivityIncluded ? null : <p className={home.balanceCaption} data-testid=\"dashboard-synthetic-balance-explainer\">Includes your simulated activity.</p>\n      ) : productSimulationActive && ready && !isLoading ? (\n        <p\n          className={home.balanceCaption}\n          data-testid=\"dashboard-synthetic-balance-explainer\"\n        >\n          Includes your simulated activity.\n        </p>\n      ) : null}\n      {ready && !isLoading && total !== available ? (\n        <p className={home.available}>\n          {syntheticJourneyActive ? \"Available in simulation:\" : \"Available now:\"}{\" \"}\n          <span className=\"font-medium text-hedgr-dark tabular-nums\">\n            ${available.toFixed(2)}\n          </span>\n          {pending !== 0 ? (\n            <span className=\"text-hedgr-400\">\n              {\" \"}\n              · Pending {pending > 0 ? \"+\" : \"\"}\n              {pending.toFixed(2)} {currency}\n            </span>\n          ) : null}\n        </p>\n      ) : null}\n  </>;\n  const balanceHero = syntheticJourneyActive ? (\n    <HomeHero label=\"Simulated Hedgr balance\" labelId=\"dashboard-total-balance-label\" usdAmount={ready && !cleanStartRequested ? displayedTotal : 0} currency={displayCurrency} ownSimulation figureTestId=\"usd-balance\" testId=\"dashboard-balance\" selector={<SimulationDisplayCurrencySelector placement=\"position\" />} loading={positionLoading} isLoading={isLoading}>\n      {balanceHeroTail}\n    </HomeHero>\n  ) : (\n    <section\n      className={`space-y-1 ${home.position}`}\n      aria-labelledby=\"dashboard-total-balance-label\"\n      data-testid=\"dashboard-balance\"\n    >\n      <div className={home.balanceHeading}>\n        <p\n          id=\"dashboard-total-balance-label\"\n          className=\"text-xs font-semibold tracking-tight text-hedgr-800\"\n        >\n          {productSimulationActive ? \"Simulated Hedgr balance\" : \"Your current position\"}\n        </p>\n        {syntheticJourneyActive ? <SimulationDisplayCurrencySelector placement=\"position\" /> : null}\n      </div>\n      {positionLoading ? (\n        <div className={home.amount} data-testid=\"dashboard-balance-loading\" aria-busy=\"true\">\n          <span className={`${home.skeleton} ${home.skeletonAmount}`} aria-hidden=\"true\" />\n          <span className={`${home.skeleton} ${home.skeletonLine}`} aria-hidden=\"true\" />\n        </div>\n      ) : isLoading ? (\n        <div className={`${home.amount} tabular-nums`}>\n          …\n        </div>\n      ) : (\n        <BalanceWithLocalEstimate\n          usdAmount={ready && !cleanStartRequested ? displayedTotal : 0}\n          data-testid=\"usd-balance\"\n          className={`${home.amount} tabular-nums`}\n        />\n      )}\n      {balanceHeroTail}\n    </section>\n  );\n\n  const productRouteHref = (\n    route: \"/deposit\" | \"/withdraw\" | \"/activity\"\n  ) => (syntheticJourneyActive ? getSyntheticJourneyHref(route) : route);\n\n  const homeUtilities = syntheticJourneyActive ? (\n    <nav aria-label=\"Simulation utilities\" className={home.utilities} data-testid=\"dashboard-simulation-utilities\">\n      <Link href={productRouteHref(\"/deposit\")} className={home.utility} data-testid=\"dashboard-add-simulated-deposit\">\n        <span>Add simulated deposit</span>\n      </Link>\n      {syntheticComparison.comparisonState === \"first-event\" ? (\n        <Link href={productRouteHref(\"/withdraw\")} className={home.utility} data-testid=\"dashboard-simulated-withdraw\">\n          <span>Simulate a withdrawal</span>\n        </Link>\n      ) : firstUse && normalPosture ? (\n        <button type=\"button\" onClick={openSimulationExplainer} className={home.utility} data-testid=\"dashboard-how-simulation-works\">\n          <span>How this simulation works</span>\n        </button>\n      ) : (\n        <Link href={productRouteHref(\"/activity\")} className={home.utility} data-testid=\"dashboard-view-activity\">\n          <span>View Activity</span>\n        </Link>\n      )}\n    </nav>\n  ) : (\n    <nav aria-label=\"Simulation utilities\" className={home.utilities} data-testid=\"dashboard-simulation-utilities\">\n      <Link href={productRouteHref(\"/deposit\")} className={home.utility} data-testid=\"dashboard-add-simulated-deposit\">\n        <span>Add simulated deposit</span>\n      </Link>\n      <Link href={productRouteHref(\"/activity\")} className={home.utility} data-testid=\"dashboard-view-activity\">\n        <span>View Activity</span>\n      </Link>\n      <Link href={productRouteHref(\"/withdraw\")} className={home.utility} data-testid=\"dashboard-simulated-withdraw\">\n        <span>Simulate a withdrawal</span>\n      </Link>\n    </nav>\n  );\n\n  const ownRateLine = syntheticJourneyActive ? <RateLine code={displayCurrency} rate={getSimulationDisplayRate(displayCurrency)} /> : null;\n\n  const observation = (\n    <div className={home.observation}>\n      <EnginePostureHeader\n        redesigned={syntheticJourneyActive}\n        engineState={engineState}\n        currencyContextVisible={currencyContextVisible}\n        syntheticJourneyActive\n        comparisonState={syntheticComparison.comparisonState}\n        latestChangeType={syntheticComparison.lastEvent?.type}\n        latestChangeAmountUSD={syntheticComparison.lastEvent?.amountUSD}\n        latestChangeCreatedAt={syntheticComparison.lastEvent?.createdAt}\n        homeDate={today}\n        changeIncludedInBalance={positionDerivable}\n      />\n      {ownRateLine}\n    </div>\n  );\n\n  const positionLine = positionDerivable ? (\n    <PositionLine entries={positionEntries} lastVisit={previousVisit} settle={arrivalSettle} visualise={syntheticJourneyActive} heroAmount={total} />\n  ) : null;\n\n  const ObservationHeading = syntheticJourneyActive ? \"h2\" : \"p\";\n  const observationLabel = (text: string) => (\n    <ObservationHeading id=\"dashboard-current-status-label\" className=\"text-sm font-semibold text-hedgr-800\">\n      {text}\n    </ObservationHeading>\n  );\n  const guaranteeLine = (\n    <p className=\"text-xs leading-relaxed text-hedgr-500\">\n      {syntheticJourneyActive && !danielExample\n        ? \"This is what happened in your simulation. It doesn’t tell you what will happen next.\"\n        : \"This is what happened in the example. It doesn’t tell you what will happen next.\"}\n    </p>\n  );\n  const activityHref = productRouteHref(\"/activity\");\n  const sinceLink = (label: string) => (\n    <Link href={activityHref} className={home.sinceLink} data-testid=\"dashboard-since-link\">\n      <span>{label}</span>\n      {syntheticJourneyActive ? null : <span aria-hidden=\"true\">→</span>}\n    </Link>\n  );\n\n  let homeObservation = observation;\n  if (normalPosture && positionLoading) {\n    homeObservation = (\n      <div className={home.observation} data-testid=\"dashboard-observation-loading\" aria-hidden=\"true\">\n        <span className={`${home.skeleton} ${home.skeletonLine}`} />\n        <span className={`${home.skeleton} ${home.skeletonLine}`} style={{ width: \"90%\" }} />\n        <span className={`${home.skeleton} ${home.skeletonLine}`} />\n      </div>\n    );\n  } else if (normalPosture && firstUse) {\n    homeObservation = (\n      <div className={home.observation}>\n        <section\n          className={`space-y-3 ${finish.observationHeader}`}\n          aria-labelledby=\"dashboard-current-status-label\"\n          data-testid=\"dashboard-current-status\"\n          data-home-state=\"first-use\"\n        >\n          {observationLabel(\"Start here\")}\n          <p className=\"max-w-xl text-sm leading-relaxed text-hedgr-dark\" data-testid=\"engine-posture-context\">\n            {syntheticJourneyActive\n              ? \"Practise with pretend money first. See what changes, and why.\"\n              : \"Practise with pretend money first. Hedgr shows what changes, and why.\"}\n          </p>\n          <ol className={home.firstUseSteps} data-testid=\"dashboard-first-use-steps\">\n            <li aria-current=\"step\">\n              {syntheticJourneyActive ? <strong>Where things stand</strong> : null}\n              <span>You are here. It starts at {formatUsd(total)}.</span>\n            </li>\n            <li>\n              {syntheticJourneyActive ? <strong>What happens</strong> : null}\n              <span>Add a simulated deposit.</span>\n            </li>\n            <li>\n              {syntheticJourneyActive ? <strong>What changed</strong> : null}\n              <span>Try a simulated withdrawal.</span>\n            </li>\n            <li>\n              {syntheticJourneyActive ? <strong>How you can tell</strong> : null}\n              <span>Check both entries in Activity.</span>\n            </li>\n          </ol>\n        </section>\n        {ownRateLine}\n      </div>\n    );\n  } else if (normalPosture && sinceSummary) {\n    homeObservation = (\n      <div className={home.observation}>\n        <section\n          className={`space-y-3 ${finish.observationHeader}`}\n          aria-labelledby=\"dashboard-current-status-label\"\n          data-testid=\"dashboard-current-status\"\n          data-home-state={`since-${sinceSummary.kind}`}\n        >\n          {observationLabel(\"Since you were last here\")}\n          {sinceSummary.kind === \"no-change\" ? (\n            <>\n              <p className=\"max-w-xl text-sm leading-relaxed text-hedgr-dark\" data-testid=\"engine-posture-context\">\n                {syntheticJourneyActive ? <>{countChanges(0, true)}</> : <>\n                  Nothing has changed since {formatShortDate(sinceSummary.since)}. Your position is still{\" \"}\n                  <span data-observation-amount>{formatUsd(sinceSummary.balance)}</span>.\n                </>}\n              </p>\n              {estimateCurrency ? (\n                <p className=\"text-sm leading-relaxed text-hedgr-600\">\n                  The {estimateCurrency} estimate can change with the exchange rate.\n                </p>\n              ) : null}\n            </>\n          ) : sinceSummary.kind === \"one\" ? (\n            <>\n              <p className=\"max-w-xl text-sm leading-relaxed text-hedgr-dark\" data-testid=\"engine-posture-context\">\n                {syntheticJourneyActive ? countChanges(1, true) : <>One simulated {sinceSummary.entry.type === \"DEPOSIT\" ? \"deposit\" : \"withdrawal\"} of{\" \"}\n                <span data-observation-amount>{formatUsd(sinceSummary.entry.amountUSD)}</span> on{\" \"}\n                {formatShortDate(sinceSummary.entry.at)}{syntheticJourneyActive ? \".\" : <>\n                  {\" \"}took your position from {formatUsd(sinceSummary.from)} to {formatUsd(sinceSummary.to)}.\n                </>}</>}\n              </p>\n              {syntheticJourneyActive ? (\n                <p className=\"text-sm leading-relaxed text-hedgr-dark\">\n                  This simulated {sinceSummary.entry.type === \"DEPOSIT\" ? \"deposit\" : \"withdrawal\"} is included in the balance above.\n                </p>\n              ) : sinceLink(\"See the entry\")}\n            </>\n          ) : (\n            <>\n              <p className=\"max-w-xl text-sm leading-relaxed text-hedgr-dark\" data-testid=\"engine-posture-context\">\n                {syntheticJourneyActive ? <>\n                  {countChanges(sinceSummary.entries.length, true)}\n                </> : <>\n                  {formatChangeCount(sinceSummary.entries.length)} things changed since{\" \"}\n                  {formatShortDate(sinceSummary.since)}. Your position went from {formatUsd(sinceSummary.from)} to{\" \"}\n                  <span data-observation-amount>{formatUsd(sinceSummary.to)}</span>.\n                </>}\n              </p>\n              {syntheticJourneyActive ? null : <ul className={home.sinceList} data-testid=\"dashboard-since-entries\">\n                {sinceSummary.entries.map((entry) => (\n                  <li key={entry.id}>\n                    <span>\n                      <strong>{entry.type === \"DEPOSIT\" ? \"Simulated deposit\" : \"Simulated withdrawal\"}</strong>\n                      <small>{formatShortDate(entry.at)}</small>\n                    </span>\n                    <span>\n                      {entry.type === \"DEPOSIT\" ? \"+\" : \"−\"}\n                      {formatUsd(entry.amountUSD)}\n                    </span>\n                  </li>\n                ))}\n              </ul>}\n              {syntheticJourneyActive ? (\n                <p className=\"text-sm leading-relaxed text-hedgr-dark\">\n                  These simulated entries are included in the balance above.\n                </p>\n              ) : sinceLink(\"See all in Activity\")}\n            </>\n          )}\n          {guaranteeLine}\n          {syntheticJourneyActive && sinceSummary.kind !== \"no-change\"\n            ? sinceLink(sinceSummary.kind === \"one\" ? \"See the entry\" : \"See all in Activity\")\n            : null}\n        </section>\n        {ownRateLine}\n      </div>\n    );\n  }\n\n  const currencyContext = currencyContextVisible ? (\n    <CurrencyInsight\n      redesigned\n      compact={syntheticJourneyActive}\n      usdAmount={total}\n      currency={displayCurrency}\n      latestDisplayRate={getSimulationDisplayRate(displayCurrency)}\n      ready={currencyContextVisible}\n      pending={currencyComparisonPending}\n    />\n  ) : null;\n\n  // §362/§365: picker and return share URL-only navigation, preserving the mounted\n  // Home and its visit guard. Neither resets nor writes the simulation.\n  const exampleHref = (value: string, search: string, path: string) => {\n    const params = new URLSearchParams(search);\n    params.delete(CLASS_A_VAL_002_RESET_PARAM);\n    if (SYNTHETIC_JOURNEY_EXAMPLES.some((example) => example.id === value)) params.set(CLASS_A_VAL_002_EXAMPLE_PARAM, value);\n    else params.delete(CLASS_A_VAL_002_EXAMPLE_PARAM);\n    const query = params.toString();\n    return `${path}${query ? `?${query}` : \"\"}`;\n  };\n  const chooseExample = (value: string) => {\n    window.history.pushState(null, \"\", exampleHref(value, window.location.search, window.location.pathname));\n  };\n  const danielPanel = danielExample ? (\n    <DanielExampleHome\n      currentRead={DANIEL_HOME_READ}\n      timeline={DANIEL_HOME_TIMELINE}\n      returnHref={exampleHref(\"own\", searchParams?.toString() ?? \"\", pathname ?? CLASS_A_VAL_002_DASHBOARD_PATH)}\n      onReturn={() => chooseExample(\"own\")}\n      limitation={guaranteeLine}\n    />\n  ) : null;\n  const examplePicker = syntheticJourneyActive ? (\n    <div className=\"mt-2 w-full min-w-0 max-w-xs\">\n      <label htmlFor=\"dashboard-example-picker\" className=\"mb-1 block text-sm font-medium text-hedgr-800\">\n        Choose an example\n      </label>\n      <div className={home.examplePicker}>\n        <span aria-hidden=\"true\" data-testid=\"example-picker-value\">\n          {SYNTHETIC_JOURNEY_EXAMPLES.find((example) => example.id === selectedExample)?.label ?? \"Your own simulation\"}\n        </span>\n        <select\n          id=\"dashboard-example-picker\"\n          value={selectedExample}\n          onChange={(event) => chooseExample(event.target.value)}\n        >\n          <option value=\"own\">Your own simulation</option>\n          {SYNTHETIC_JOURNEY_EXAMPLES.map((example) => (\n            <option key={example.id} value={example.id}>{example.label}</option>\n          ))}\n        </select>\n      </div>\n    </div>\n  ) : null;\n\n  const currentOverview = (\n    <section\n      aria-label={\n        productSimulationActive\n          ? \"Current simulation overview\"\n          : \"Current account overview\"\n      }\n      className={home.overview}\n      data-testid=\"dashboard-current-overview\"\n    >\n      {syntheticJourneyActive ? (\n        <>\n          <div className={home.overviewGrid}>\n            <div className={home.positionPanel}>\n              {balanceHero}\n              {positionLine}\n            </div>\n            <div className={home.insights}>\n              {homeObservation}\n              {homeUtilities}\n            </div>\n          </div>\n          {currencyContext}\n        </>\n      ) : productSimulationActive ? (\n        <div className={home.overviewGrid}>\n          <div className={home.positionPanel}>{balanceHero}{positionLine}</div>\n          <div className={home.insights}>\n          {homeObservation}\n          {homeUtilities}\n          {currencyContext}\n          </div>\n        </div>\n      ) : (\n        <div className={home.overviewGrid}>\n          <div className={home.positionPanel}>{balanceHero}</div>\n          <div className={home.observation}>\n            <EnginePostureHeader engineState={engineState} />\n          </div>\n        </div>\n      )}\n    </section>\n  );\n\n  const accordionChevron = (\n    <span className={home.chevron} aria-hidden=\"true\">\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.5\" focusable=\"false\">\n        <path d=\"m7 10 5 5 5-5\" strokeLinecap=\"round\" strokeLinejoin=\"round\" />\n      </svg>\n    </span>\n  );\n\n  const educationSection = syntheticJourneyActive ? null : (\n    <details className={home.accordion} data-testid=\"dashboard-education\">\n      <summary className={home.accordionSummary}>\n        <span>How Hedgr interprets stability</span>\n        {accordionChevron}\n      </summary>\n      <div className={`${home.accordionContent} space-y-3`}>\n        <EngineStabilityReviewSnapshot engineState={engineState} />\n        <EngineProtectiveGuidance />\n        <EngineStabilityExplainer />\n      </div>\n    </details>\n  );\n\n\n  const disclosureSection = (\n    <details\n      className={home.accordion}\n      data-testid=\"dashboard-disclosures\"\n    >\n      <summary className={home.accordionSummary}><span>Important disclosures</span>{accordionChevron}</summary>\n      <div className={home.accordionContent}>\n        <PolicyDisclosure\n          context={syntheticJourneyActive ? \"synthetic-research\" : \"default\"}\n        />\n      </div>\n    </details>\n  );\n\n  if (error && !exampleActive) {\n    return (\n      <main className={`${home.page} ${home.scopeFirst}`}>\n        <div\n          className={`mx-auto space-y-6 sm:space-y-8 ${\n            productSimulationActive ? \"max-w-5xl\" : \"max-w-2xl\"\n          }`}\n        >\n          {currentOverview}\n          <EngineAllocationBands\n            engineState={engineState}\n            collapsed={productSimulationActive}\n          />\n          <ErrorState\n            title=\"Unable to load your balance\"\n            description=\"We couldn't fetch your account balance. Please try again.\"\n            primaryAction={{ label: \"Retry\", onClick: refresh }}\n            data-testid=\"dashboard-error-state\"\n          />\n          {educationSection}\n          {disclosureSection}\n        </div>\n      </main>\n    );\n  }\n\n  return (\n    <main className={`${home.page} ${home.scopeFirst}`}>\n      <div\n        className={home.content}\n      >\n        <section\n          aria-labelledby=\"dashboard-orientation-heading\"\n          className=\"space-y-0.5 pb-1 sm:space-y-2\"\n          data-testid=\"dashboard-orientation\"\n        >\n          {productSimulationActive && !exampleActive && today !== null ? (\n            <p className={home.dateLine} data-testid=\"dashboard-date-line\">\n              {formatDateLine(today)}\n            </p>\n          ) : null}\n          <h1\n            id=\"dashboard-orientation-heading\"\n            className=\"text-xl font-bold tracking-tight text-hedgr-800 sm:text-4xl\"\n          >\n            {syntheticJourneyActive ? exampleActive ? \"Example\" : \"Your simulation\" : \"Your position\"}\n          </h1>\n          {examplePicker}\n          {!syntheticJourneyActive ? <p className={home.contextLine} data-testid=\"dashboard-context-line\">\n            {productSimulationActive\n              ? 'This simulated experience provides context, not an instruction.'\n              : 'This experience provides context, not an instruction.'}\n          </p> : null}\n        </section>\n\n        {sarahExample ? <SarahExampleHome read={SARAH_HOME_READ} /> : danielExample ? danielPanel : currentOverview}\n\n        {isFirstTimeUser && !productSimulationActive && (\n          <div\n            className=\"rounded-2xl border border-hedgr-200 bg-hedgr-100/60 p-5 text-hedgr-800 sm:p-6\"\n            data-testid=\"dashboard-empty-state\"\n          >\n            <div className=\"flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between\">\n              <div className=\"max-w-lg\">\n                <p className=\"text-[11px] font-semibold uppercase tracking-[0.12em] text-hedgr-500\">\n                  Primary journey action\n                </p>\n                <h2 className=\"mt-1 text-lg font-semibold text-hedgr-800\">\n                  See your position clearly\n                </h2>\n                <p className=\"mt-1 text-sm leading-relaxed text-hedgr-dark\">\n                  Start by exploring a deposit when you are ready. Your balance\n                  and activity will appear here once you begin.\n                </p>\n              </div>\n              <Link\n                href=\"/deposit\"\n                className=\"inline-flex shrink-0 items-center justify-center rounded-xl bg-hedgr-primary px-4 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-hedgr-600 focus:outline-none focus:ring-2 focus:ring-hedgr-500 focus:ring-offset-2 focus:ring-offset-hedgr-100\"\n              >\n                Make your first deposit\n              </Link>\n            </div>\n          </div>\n        )}\n\n        {exampleActive ? (\n          <div className={home.support}>{disclosureSection}</div>\n        ) : syntheticJourneyActive ? (\n          <div className={home.support}>\n            <details className={home.accordion} data-testid=\"research-planning-targets\">\n              <summary className={home.accordionSummary}>\n                <span>Planning targets<span className={home.accordionSubtitle}>Targets only · No money moved</span></span>\n                {accordionChevron}\n              </summary>\n              <div className={home.accordionContent}><EngineAllocationBands engineState={engineState} collapsed /></div>\n            </details>\n            {disclosureSection}\n          </div>\n        ) : null}\n\n\n\n        {syntheticJourneyActive && !exampleActive && hasSyntheticFixtureState && (\n          <section\n            className={`${finish.replay} text-hedgr-800`}\n            data-testid=\"dashboard-restart-journey\"\n            aria-labelledby=\"dashboard-restart-journey-heading\"\n          >\n            <div className=\"flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between\">\n              <div className=\"max-w-lg\">\n                <p className=\"text-[11px] font-semibold uppercase tracking-[0.12em] text-hedgr-500\">\n                  Simulated journey replay\n                </p>\n                <h2\n                  id=\"dashboard-restart-journey-heading\"\n                  className=\"mt-1 text-base font-semibold text-hedgr-800\"\n                >\n                  Run the simulated journey again\n                </h2>\n                <p className=\"mt-1 text-sm leading-relaxed text-hedgr-dark\">\n                  Restarting removes only this device&apos;s simulated position\n                  and Activity so the example begins again at $0. No real money\n                  or external records are affected.\n                </p>\n              </div>\n              <button\n                type=\"button\"\n                onClick={restartSyntheticJourney}\n                className=\"inline-flex min-h-11 shrink-0 items-center justify-center rounded-xl border border-hedgr-200 bg-white px-4 py-2.5 text-sm font-semibold text-hedgr-800 transition-colors hover:border-hedgr-300 focus:outline-none focus:ring-2 focus:ring-hedgr-500 focus:ring-offset-2\"\n              >\n                Restart simulated journey\n              </button>\n            </div>\n          </section>\n        )}\n\n        {!syntheticJourneyActive && !isFirstTimeUser && !hasNoTransactions && !sinceChangesShown && (\n          <section\n            className=\"border-t border-hedgr-200 pt-6\"\n            aria-labelledby=\"dashboard-recent-activity-heading\"\n          >\n            <div className=\"flex flex-wrap items-baseline justify-between gap-3\">\n              <h2\n                id=\"dashboard-recent-activity-heading\"\n                className=\"text-base font-semibold tracking-tight text-hedgr-800\"\n              >\n                Recent activity\n              </h2>\n              <Link\n                href=\"/activity\"\n                className=\"shrink-0 text-sm font-medium text-hedgr-600 underline-offset-2 hover:text-hedgr-primary hover:underline\"\n              >\n                View all\n              </Link>\n            </div>\n            <ul className=\"mt-4 divide-y divide-hedgr-100 border-t border-hedgr-100\">\n              {recentActivity.map((tx) => (\n                <li\n                  key={tx.id}\n                  className=\"flex flex-wrap items-baseline justify-between gap-4 py-3\"\n                >\n                  <div className=\"min-w-0\">\n                    <p className=\"font-medium text-hedgr-800\">\n                      {activityTitle(tx, productSimulationActive)}\n                    </p>\n                    <p className=\"text-sm text-hedgr-500\">\n                      {formatActivityDayLabel(tx.createdAt)}\n                    </p>\n                  </div>\n                  <p\n                    className={`shrink-0 tabular-nums text-sm font-semibold ${\n                      tx.type === \"DEPOSIT\"\n                        ? \"text-hedgr-600\"\n                        : \"text-hedgr-dark\"\n                    }`}\n                  >\n                    {tx.type === \"DEPOSIT\" ? \"+\" : \"-\"}$\n                    {tx.amountUSD.toFixed(2)}\n                  </p>\n                </li>\n              ))}\n            </ul>\n          </section>\n        )}\n\n        {(!syntheticJourneyActive || !explicitSyntheticJourney) &&\n          isFeatureEnabled(\"earn\") && (\n            <div className=\"max-w-sm\">\n              <div\n                className=\"rounded-xl border border-hedgr-200 bg-white p-4\"\n                data-testid=\"dashboard-earn-tile\"\n              >\n                <div className=\"text-xs font-medium text-hedgr-500\">\n                  Example annual yield (APY)\n                </div>\n                <p className=\"mt-1 text-xs text-hedgr-800\">\n                  {ENGINE_ILLUSTRATIVE_VALUES_LABEL}\n                </p>\n                {apyError ? (\n                  <div className=\"mt-1 text-xs font-medium text-hedgr-800\">\n                    {apyError}\n                  </div>\n                ) : (\n                  <div className=\"mt-1 text-xl font-semibold tabular-nums text-hedgr-dark\">\n                    {apy !== null ? `${(apy * 100).toFixed(2)}%` : \"Example yield unavailable\"}\n                  </div>\n                )}\n              </div>\n            </div>\n          )}\n\n        {!productSimulationActive && !isFirstTimeUser && hasNoTransactions && (\n          <div className=\"rounded-2xl border border-hedgr-200 bg-white p-6\">\n            <h2 className=\"mb-4 text-lg font-semibold\">Nothing needs action</h2>\n            <EmptyState\n              title=\"Nothing has changed\"\n              description=\"Nothing has changed that requires a decision. Check again when you want an update.\"\n              className=\"py-8\"\n              data-testid=\"dashboard-no-actions\"\n            />\n          </div>\n        )}\n\n        {!syntheticJourneyActive ? (\n          <div className={home.support}>\n            {productSimulationActive || !isFirstTimeUser ? (\n              <details className={home.accordion} data-testid=\"dashboard-planning-targets\">\n                <summary className={home.accordionSummary}>\n                  <span>Planning targets{productSimulationActive ? <span className={home.accordionSubtitle}>Targets only · No money moved</span> : null}</span>\n                  {accordionChevron}\n                </summary>\n                <div className={home.accordionContent}><EngineAllocationBands engineState={engineState} collapsed={productSimulationActive} /></div>\n              </details>\n            ) : null}\n            {educationSection}\n            {disclosureSection}\n          </div>\n        ) : null}\n      </div>\n    </main>\n  );\n}\n",
  "lib/engine/stability-explainer-copy.ts": "/**\n * Ticket-local copy for the MC-S2-009 expandable explainer (dashboard allocation surface).\n * Principle-level posture only. Does not duplicate ENGINE_POSTURE_CONTEXT or ENGINE_NOTICE_COPY.\n */\n\nexport const ENGINE_STABILITY_EXPLAINER_SUMMARY =\n  'Why your balance is structured this way';\n\n/** One short intro line (informational framing). */\nexport const ENGINE_STABILITY_EXPLAINER_INTRO =\n  'Plain-language definitions for the labels above. This is informational posture, not ledger truth.';\n\nexport const ENGINE_STABILITY_EXPLAINER_TERMS: ReadonlyArray<{\n  term: string;\n  definition: string;\n}> = [\n  {\n    term: 'Stable balance',\n    definition: 'The primary holding lane. It is held steady to preserve value.',\n  },\n  {\n    term: 'Conservative yield',\n    definition:\n      'A supporting lane. Up to this target can support returns when conditions allow.',\n  },\n  {\n    term: 'Reserve',\n    definition: 'A quiet buffer. It is kept ready in principle if you need it.',\n  },\n];\n\nexport const ENGINE_STABILITY_EXPLAINER_PRINCIPLES: readonly string[] = [\n  'Most of the structure is held steady. Conservative yield and a reserve are quieter supporting lanes. This shows system intent, not a map of where funds sit.',\n  'When the system is more cautious, protection and the reserve can outweigh conservative yield. Posture reflects that caution. It does not describe completed movement.',\n];\n\nexport const ENGINE_STABILITY_EXPLAINER_FOOTER =\n  'Targets are not accounting truth. Your ledger shows balances. These bands do not mean funds have moved.';\n",
  "lib/engine/protective-guidance-copy.ts": "/**\n * Ticket-local copy for MC-S2-010 protective guidance (dashboard allocation surface).\n * Principle-level only. Does not duplicate ENGINE_POSTURE_CONTEXT or ENGINE_NOTICE_COPY.\n */\n\nexport const ENGINE_PROTECTIVE_GUIDANCE_TITLE = 'Protection in plain terms';\n\n/** One framing paragraph: deliberate intent, not operational status. */\nexport const ENGINE_PROTECTIVE_GUIDANCE_FRAMING =\n  'Hedgr treats stability and protection as deliberate design choices. In tougher conditions, these informational targets may emphasize protection and liquidity ahead of conservative yield. That is visible intent you can review, not a nudge to move funds.';\n\nexport const ENGINE_PROTECTIVE_GUIDANCE_POINTS: readonly string[] = [\n  'Caution can limit conservative yield before protection is stressed. The split reflects that priority, not completed movement.',\n  'The Reserve above still means readiness in principle. Targets are informational, not your ledger balance.',\n  'A protective posture does not by itself stop a withdrawal from processing or imply lockup.',\n];\n",
  "lib/engine/stability-review-snapshot-copy.ts": "import type { EnginePosture } from './types';\n\n/**\n * Ticket-local copy for MC-S2-011 review snapshot, MC-S2-012 cadence cue,\n * MC-S2-013 change signal, and MC-S2-014 recent stability memory (same-vs-last-view).\n * Minimal scope only. Does not duplicate ENGINE_POSTURE_CONTEXT or notice copy.\n */\n\nexport const ENGINE_STABILITY_REVIEW_SNAPSHOT_TITLE = 'Review snapshot';\n\nexport const ENGINE_ILLUSTRATIVE_VALUES_LABEL =\n  'Illustrative example values, not live targets or advice';\n\nconst STANCE_BY_POSTURE: Record<EnginePosture, string> = {\n  normal: 'Where things stand: within expected range',\n  tightening: 'Where things stand: protective posture increasing',\n  tightened: 'Where things stand: protective posture elevated',\n  recovery: 'Where things stand: within expected range, easing steadily',\n};\n\nexport function getEngineStabilityReviewSnapshotStance(\n  posture: EnginePosture,\n): string {\n  return STANCE_BY_POSTURE[posture];\n}\n\nexport const ENGINE_STABILITY_REVIEW_AVAILABLE_CONTINUITY =\n  '“Available” still means ready to use in principle; these targets stay informational.';\n\nexport const ENGINE_STABILITY_REVIEW_WITHDRAWAL_CONTINUITY =\n  'A protective posture does not, on its own, mean withdrawals are blocked or delayed.';\n\nexport const ENGINE_STABILITY_REVIEW_CADENCE_CUE =\n  'Use this snapshot for a calm, regular check-in. Protective conditions stay visible here without nudging you to act.';\n\nexport function getEngineStabilityReviewTimestampLine(\n  formattedUpdatedAt: string,\n): string {\n  return `Snapshot reflects current system targets as of ${formattedUpdatedAt}.`;\n}\n\n/** MC-S2-013 — shown only when a prior local fingerprint exists (not first visit). */\nexport const ENGINE_STABILITY_REVIEW_CHANGE_UNCHANGED =\n  'Since you last opened this review snapshot in this browser, the informational system targets shown here are unchanged.';\n\nexport const ENGINE_STABILITY_REVIEW_CHANGE_CHANGED =\n  'Since you last opened this review snapshot in this browser, the informational system targets shown here differ from what you last saw.';\n\n/** Frames comparison as review/system targets, not balances or movement (ADR 0013). */\nexport const ENGINE_STABILITY_REVIEW_CHANGE_DISCLAIMER =\n  'This comparison is about system targets for this review only. It is not your ledger balances or whether funds moved.';\n\n/** MC-S2-014 — orientation-first; not interaction history, trail, or feed language. */\nexport const ENGINE_STABILITY_REVIEW_MEMORY_TITLE = 'Recent readings';\n\n/** Memory aid in this browser only, not a system record or operational history. */\nexport const ENGINE_STABILITY_REVIEW_MEMORY_DISCLAIMER =\n  'Saved only on this device for your orientation. It is not a record of balances, execution, or backend events.';\n\n/** Short row lines; same meaning as MC-S2-013, without repeating full paragraphs. */\nexport const ENGINE_STABILITY_REVIEW_MEMORY_TARGETS_UNCHANGED =\n  'Informational targets unchanged since your prior check.';\n\nexport const ENGINE_STABILITY_REVIEW_MEMORY_TARGETS_CHANGED =\n  'Informational targets differ from your prior check.';\n",
  "app/(app)/dashboard/EngineAllocationBands.tsx": "\"use client\";\n\nimport finish from '../product-finish.module.css';\n\nimport React from \"react\";\nimport type { EngineState } from \"../../../lib/engine/types\";\nimport { ENGINE_ILLUSTRATIVE_VALUES_LABEL } from \"../../../lib/engine/stability-review-snapshot-copy\";\n\ntype EngineAllocationBandsProps = {\n  engineState: EngineState;\n  collapsed?: boolean;\n};\n\ntype LaneKey = \"liquidityTargetPct\" | \"coreTargetPct\" | \"yieldCapPct\";\n\n// These are planning roles, not funded containers. Order and labels remain\n// fixed across postures so the guidance stays legible without colour or a\n// portfolio-style allocation graphic.\nconst GUIDANCE_LANES: Array<{\n  key: LaneKey;\n  label: string;\n  role: string;\n}> = [\n  {\n    key: \"coreTargetPct\",\n    label: \"Core stability target\",\n    role: \"Primary stability guidance\",\n  },\n  {\n    key: \"yieldCapPct\",\n    label: \"Conservative yield\",\n    role: \"Supporting guidance\",\n  },\n  {\n    key: \"liquidityTargetPct\",\n    label: \"Reserve\",\n    role: \"Supporting guidance\",\n  },\n];\n\nfunction formatPct(value: number) {\n  return `${value}%`;\n}\n\nfunction laneDescription(key: LaneKey): string {\n  switch (key) {\n    case \"coreTargetPct\":\n      return \"The largest target, focused on preserving value.\";\n    case \"yieldCapPct\":\n      return \"A limited target for return opportunity when conditions allow.\";\n    case \"liquidityTargetPct\":\n      return \"A buffer target, kept ready if needed.\";\n  }\n}\n\nconst TARGET_ROLES: Array<{\n  key: LaneKey;\n  label: string;\n  role: string;\n  description: string;\n}> = [\n  {\n    key: \"coreTargetPct\",\n    label: \"Core stability target\",\n    role: \"Primary stability role\",\n    description: \"Preserve value as the primary stability priority.\",\n  },\n  {\n    key: \"yieldCapPct\",\n    label: \"Conservative yield\",\n    role: \"Supporting role\",\n    description: \"Keep return opportunity limited and conditional.\",\n  },\n  {\n    key: \"liquidityTargetPct\",\n    label: \"Reserve\",\n    role: \"Supporting role\",\n    description: \"Keep a buffer ready if needed.\",\n  },\n];\n\nconst SYNTHETIC_PURPOSES: Array<{\n  key: LaneKey;\n  label: string;\n  description: string;\n}> = [\n  {\n    key: \"coreTargetPct\",\n    label: \"Now\",\n    description: \"For what matters in the near term.\",\n  },\n  {\n    key: \"liquidityTargetPct\",\n    label: \"Reserve\",\n    description: \"A buffer for surprises and setbacks.\",\n  },\n  {\n    key: \"yieldCapPct\",\n    label: \"Growth\",\n    description: \"For future opportunities.\",\n  },\n];\n\nexport function EngineAllocationBands({\n  engineState,\n  collapsed = false,\n}: EngineAllocationBandsProps) {\n  const syntheticPlanning = (\n    <div className=\"space-y-4\">\n      <dl\n        className={`overflow-hidden ${finish.purposes}`}\n        data-testid=\"engine-allocation-target-roles\"\n        aria-label=\"Planning purposes\"\n      >\n        {SYNTHETIC_PURPOSES.map(({ key, label, description }) => (\n          <div\n            key={key}\n            className={finish.purpose}\n            data-testid={`engine-allocation-role-${key}`}\n          >\n            <dt className=\"text-sm font-semibold text-hedgr-800\">{label}</dt>\n            <dd className=\"mt-1 text-xs leading-relaxed text-hedgr-500 sm:text-sm\">\n              {description}\n            </dd>\n          </div>\n        ))}\n      </dl>\n\n      <p\n        className={`max-w-2xl text-hedgr-dark ${finish.planningBoundary}`}\n        data-testid=\"engine-allocation-boundary\"\n      >\n        These are planning purposes, not separate balances. They do not divide\n        or move simulated money.\n      </p>\n\n      <details data-testid=\"engine-allocation-values-details\">\n        <summary className=\"inline-flex min-h-11 cursor-pointer items-center text-sm font-semibold text-hedgr-600 hover:text-hedgr-primary focus:outline-none focus:ring-2 focus:ring-hedgr-500 focus:ring-offset-2\">\n          View planning percentages\n        </summary>\n        <p className=\"mt-4 text-xs leading-relaxed text-hedgr-500\">\n          {ENGINE_ILLUSTRATIVE_VALUES_LABEL}\n        </p>\n        <dl\n          className=\"mt-4 divide-y divide-hedgr-100 border-y border-hedgr-100\"\n          data-testid=\"engine-allocation-structure\"\n        >\n          {SYNTHETIC_PURPOSES.map(({ key, label }) => (\n            <div\n              key={key}\n              className=\"flex items-center justify-between gap-4 py-3\"\n              data-testid={`engine-allocation-band-${key}`}\n              data-guidance-row=\"true\"\n            >\n              <dt className=\"text-sm font-medium text-hedgr-800\">{label}</dt>\n              <dd className=\"text-sm font-semibold tabular-nums text-hedgr-800\">\n                {formatPct(engineState[key])}\n              </dd>\n            </div>\n          ))}\n        </dl>\n        <p className=\"mt-3 text-xs leading-relaxed text-hedgr-500\">\n          The percentages show how the plan is divided in this example. No real money is split or moved.\n        </p>\n      </details>\n    </div>\n  );\n\n  const priorities = (\n    <p\n      className=\"max-w-xl text-sm leading-relaxed text-hedgr-dark\"\n      data-testid=\"engine-allocation-philosophy\"\n    >\n      Hedgr&apos;s guidance makes its priorities visible in this simulation:\n      preserve value first, keep access and risk visible, and understand the\n      situation before action.\n    </p>\n  );\n\n  const targetRoles = (\n    <div\n      className=\"space-y-3\"\n      data-testid=\"engine-allocation-target-roles\"\n      aria-label=\"Stability target roles\"\n    >\n      <p className=\"max-w-xl text-sm leading-relaxed text-hedgr-dark\">\n        Hedgr represents those priorities through three distinct target roles.\n      </p>\n      <dl className=\"divide-y divide-hedgr-100 border-y border-hedgr-100\">\n        {TARGET_ROLES.map(({ key, label, role, description }) => (\n          <div\n            key={key}\n            className=\"grid gap-1 py-3 sm:grid-cols-[minmax(0,1fr)_minmax(0,1.5fr)] sm:gap-4\"\n            data-testid={`engine-allocation-role-${key}`}\n          >\n            <dt>\n              <span className=\"block text-sm font-semibold text-hedgr-800\">\n                {label}\n              </span>\n              <span className=\"mt-0.5 block text-[11px] font-medium uppercase tracking-wide text-hedgr-500\">\n                {role}\n              </span>\n            </dt>\n            <dd className=\"text-sm leading-relaxed text-hedgr-dark\">\n              {description}\n            </dd>\n          </div>\n        ))}\n      </dl>\n    </div>\n  );\n\n  const targetValues = (\n    <>\n      <p\n        className=\"max-w-xl text-sm leading-relaxed text-hedgr-dark\"\n        data-testid=\"engine-allocation-targets-intro\"\n      >\n        These percentages describe a simulated planning structure for those\n        roles. They are guidance, not current money.\n      </p>\n\n      <dl\n        className=\"divide-y divide-hedgr-100 border-y border-hedgr-100\"\n        data-testid=\"engine-allocation-structure\"\n      >\n        {GUIDANCE_LANES.map(({ key, label, role }, index) => {\n          const value = engineState[key];\n          const descId = `engine-allocation-band-${key}-desc`;\n\n          return (\n            <div\n              key={key}\n              className=\"grid gap-3 py-4 sm:grid-cols-[minmax(0,1fr)_auto] sm:items-center sm:gap-6\"\n              data-testid={`engine-allocation-band-${key}`}\n              data-allocation-lane={index === 0 ? \"primary\" : \"supporting\"}\n              data-guidance-row=\"true\"\n              aria-describedby={descId}\n            >\n              <div>\n                <dt>\n                  <span className=\"block text-sm font-semibold text-hedgr-800\">\n                    {label}\n                  </span>\n                  <span className=\"mt-0.5 block text-[11px] font-medium uppercase tracking-wide text-hedgr-500\">\n                    {role}\n                  </span>\n                </dt>\n                <dd\n                  id={descId}\n                  className=\"mt-1 text-sm leading-relaxed text-hedgr-dark\"\n                >\n                  {laneDescription(key)}\n                </dd>\n              </div>\n              <dd className=\"flex items-baseline justify-between gap-3 sm:block sm:min-w-24 sm:text-right\">\n                <span className=\"text-[11px] font-medium uppercase tracking-wide text-hedgr-500\">\n                  Stability target\n                </span>\n                <span className=\"block text-lg font-semibold tabular-nums text-hedgr-800\">\n                  {formatPct(value)}\n                </span>\n              </dd>\n            </div>\n          );\n        })}\n      </dl>\n\n      <aside\n        className=\"max-w-xl border-l-2 border-hedgr-200 pl-3 text-sm leading-relaxed text-hedgr-dark\"\n        data-testid=\"engine-allocation-boundary\"\n        aria-label=\"Stability guidance boundary\"\n      >\n        <span className=\"font-semibold text-hedgr-800\">Guidance only.</span>{\" \"}\n        This planning structure is context, not an instruction. It does not show\n        current money or prove that simulated money was divided or moved.\n      </aside>\n\n      <aside\n        className=\"max-w-xl border-t border-hedgr-100 pt-4 text-xs leading-relaxed text-hedgr-dark\"\n        data-testid=\"engine-allocation-trust-legend\"\n        aria-label=\"Detailed stability target distinction\"\n      >\n        <p>\n          <span className=\"font-semibold text-hedgr-800\">Planning targets</span>\n          . The percentages show intended stability priorities in this\n          simulation only.\n        </p>\n        <details\n          className=\"mt-3\"\n          data-testid=\"engine-allocation-target-details\"\n        >\n          <summary className=\"inline-flex min-h-11 cursor-pointer items-center font-medium text-hedgr-600 underline decoration-hedgr-200 underline-offset-4\">\n            Verify what stability targets mean\n          </summary>\n          <div className=\"mt-3 space-y-2 border-l border-hedgr-200 pl-3\">\n            <p>\n              <span className=\"font-semibold text-hedgr-800\">Target role</span>.\n              A lower Conservative yield target limits the return opportunity\n              shown within the guidance.\n            </p>\n            <p>\n              <span className=\"font-semibold text-hedgr-800\">\n                Current state\n              </span>\n              . The simulated balance shown above is separate from this\n              guidance. The percentages do not divide it.\n            </p>\n            <p>\n              <span className=\"font-semibold text-hedgr-800\">\n                No instruction or movement\n              </span>\n              . Guidance does not tell you what to do, and a target does not\n              divide or move simulated money.\n            </p>\n          </div>\n        </details>\n      </aside>\n    </>\n  );\n\n  return (\n    <section\n      aria-labelledby=\"engine-allocation-bands-title\"\n      className={\n        collapsed\n          ? \"space-y-4 border-t border-hedgr-100 bg-white pt-5 sm:pt-6\"\n          : \"space-y-5 rounded-2xl border border-hedgr-100 bg-white p-5 shadow-sm sm:p-6\"\n      }\n      data-testid=\"engine-allocation-bands\"\n      data-presentation={collapsed ? \"collapsed\" : \"expanded\"}\n    >\n      <div className=\"space-y-2\">\n        <h2\n          id=\"engine-allocation-bands-title\"\n          className=\"text-lg font-semibold tracking-tight text-hedgr-800\"\n        >\n          {collapsed ? \"What you are building toward\" : \"Stability guidance\"}\n        </h2>\n        {!collapsed ? (\n          <p className=\"text-xs leading-relaxed text-hedgr-500\">\n            {ENGINE_ILLUSTRATIVE_VALUES_LABEL}\n          </p>\n        ) : null}\n        <p\n          className=\"max-w-xl text-sm leading-relaxed text-hedgr-500\"\n          data-testid=\"engine-allocation-bands-caption\"\n        >\n          {collapsed\n            ? \"Three purposes for planning ahead. They are guidance, not money set aside.\"\n            : \"See the planning position shown in this simulation and why it is structured this way. These targets are guidance, not current money.\"}\n        </p>\n      </div>\n\n      {collapsed ? (\n        syntheticPlanning\n      ) : (\n        <div className=\"space-y-5\">\n          {priorities}\n          {targetRoles}\n          {targetValues}\n        </div>\n      )}\n    </section>\n  );\n}\n",
  "app/(app)/dashboard/CurrencyInsight.tsx": "import { useRef } from 'react';\nimport wallet from '../research-wallet.module.css';\nimport type { SimulationDisplayCurrency } from '../../../lib/state/simulation-display-currency';\nimport {\n  compareCurrencyExample,\n  formatComparisonCents,\n  makeCurrencyExample,\n  type CurrencyExample,\n} from '../../../lib/narrative/simulation-currency-insight';\nimport styles from './currency-insight.module.css';\n\ntype CurrencyInsightProps = {\n  usdAmount: number;\n  currency: SimulationDisplayCurrency;\n  latestDisplayRate: number;\n  ready: boolean;\n  pending?: boolean;\n  /** Explicit synthetic samples for isolated review/tests, never a runtime selector. */\n  example?: CurrencyExample;\n  redesigned?: boolean;\n  /** Synthetic Home only: keep the complete comparison inside its dialog. */\n  compact?: boolean;\n};\n\nexport function CurrencyInsight({\n  usdAmount, currency, latestDisplayRate, ready, pending = false,\n  example = makeCurrencyExample(latestDisplayRate), redesigned = false, compact = false,\n}: CurrencyInsightProps) {\n  const dialogRef = useRef<HTMLDialogElement>(null);\n  const triggerRef = useRef<HTMLButtonElement>(null);\n  if (!ready) return null;\n  const result = compareCurrencyExample({ usdAmount, latestDisplayRate, example, pending });\n  const comparison = result.kind === 'comparison' ? result : null;\n  const headline = comparison\n    ? comparison.direction === 'equal' ? 'No exchange-rate difference'\n      : comparison.direction === 'rounded-zero' ? 'No difference at this display precision'\n        : `${currency} ${formatComparisonCents(comparison.deltaCents, true)} ${comparison.direction} from the rate change`\n    : result.kind === 'empty' ? 'No position to compare yet.' : 'Currency comparison unavailable.';\n\n  if (redesigned) {\n    const limit = 'FX comparison only—not earnings, purchasing power, guaranteed protection or a conversion quote.';\n    const summary = (<>{comparison && (comparison.direction === 'higher' || comparison.direction === 'lower') ? <>\n          <p className={styles.estimateLabel}>Change in {currency} estimate</p>\n          <p className={styles.summary} data-testid=\"currency-insight-headline\">\n            <span className={styles.difference} data-testid=\"currency-insight-difference\">{currency} {formatComparisonCents(comparison.deltaCents, true)}</span>{' '}\n            <span className={styles.cause}><span className={styles.direction} aria-hidden=\"true\" data-testid=\"currency-insight-direction\" data-direction={comparison.direction} />{comparison.direction} from the rate change</span>\n          </p>\n        </> : <p className={wallet.headline} data-testid=\"currency-insight-headline\">\n          {comparison ? <span className={styles.direction} aria-hidden=\"true\" data-testid=\"currency-insight-direction\">—</span> : null}\n          <span>{headline}</span>\n        </p>}</>);\n    return (\n      <section className={`${wallet.context} ${styles.refined} ${compact ? styles.compact : \"\"}`} aria-label=\"Currency context\" data-testid=\"currency-insight\">\n        {!compact || !comparison ? <p className={styles.period}>30-day example · Simulated</p> : null}\n        {(!compact || !comparison) ? summary : null}\n        {comparison ? <>\n          {!compact ? <p>Your USD amount is held constant in this comparison.</p> : null}\n          <button ref={triggerRef} type=\"button\" className={compact ? styles.launcher : wallet.link} aria-label={compact ? 'Currency context' : undefined} aria-describedby={compact ? 'currency-context-inline-insight' : undefined} aria-haspopup=\"dialog\" onClick={() => dialogRef.current?.showModal()}>\n            {compact ? <span className={styles.launcherContent}>\n              <span>Currency context</span>\n              <span className={styles.launcherSubtitle}>30-day example · Simulated</span>\n              <span id=\"currency-context-inline-insight\" className={styles.launcherInsight} data-testid=\"currency-insight-inline\">\n                {comparison.direction === 'higher' || comparison.direction === 'lower' ? <>\n                  <span className={styles.launcherDelta}>{currency} {formatComparisonCents(comparison.deltaCents, true)} {comparison.direction}</span>{' '}\n                  <span className={styles.launcherCause}>from the rate change</span>\n                </> : headline}\n              </span>\n              <span className={styles.launcherAffordance}>Understand the comparison <span aria-hidden=\"true\">→</span></span>\n            </span> : 'Understand the comparison'}\n          </button>\n          {!compact ? <p className={wallet.limit}>{limit}</p> : null}\n          <dialog ref={dialogRef} className={wallet.dialog} aria-labelledby=\"currency-context-title\" onClose={() => triggerRef.current?.focus()} onKeyDown={event => {\n            if (event.key !== 'Tab') return;\n            const controls = event.currentTarget.querySelectorAll<HTMLElement>('button, summary');\n            const first = controls[0];\n            const last = controls[controls.length - 1];\n            if (event.shiftKey && document.activeElement === first) {\n              event.preventDefault();\n              last?.focus();\n            } else if (!event.shiftKey && document.activeElement === last) {\n              event.preventDefault();\n              first?.focus();\n            }\n          }}>\n            <div className={wallet.dialogStrip}>Simulation · No real money</div>\n            <div className={wallet.page}>\n              <div className={wallet.dialogHeader}>\n                <button type=\"button\" onClick={() => dialogRef.current?.close()}>Back to Home</button>\n                <h2 id=\"currency-context-title\">Currency context</h2>\n              </div>\n              <p>30-day example · Simulated</p>\n              <h3 className={wallet.dialogTitle}>Same USD amount.<br />{comparison.direction === 'equal' ? 'Same local estimate.' : comparison.direction === 'rounded-zero' ? 'Same estimate at this display precision.' : 'Different local estimate.'}</h3>\n              <p>This shows the same amount at two made-up exchange rates. No money is earned or exchanged, and it isn’t what you’d receive.</p>\n              <div className={wallet.comparison}>\n                <dl>\n                  <div className={wallet.comparisonRow}><dt>Day 0<span>1 USD = {comparison.earlierRate.toLocaleString('en-US', { maximumFractionDigits: 20 })} {currency}</span></dt><dd>{currency} {formatComparisonCents(comparison.earlierCents)}</dd></div>\n                  <div className={wallet.comparisonRow}><dt>Day 30<span>1 USD = {comparison.latestRate.toLocaleString('en-US', { maximumFractionDigits: 20 })} {currency}</span></dt><dd>{currency} {formatComparisonCents(comparison.latestCents)}</dd></div>\n                </dl>\n                {compact ? summary : <p className={wallet.headline}>{headline}</p>}\n              </div>\n              <section><h2>What this means</h2><p>{comparison.direction === 'equal' ? 'The exchange rates are equal in this comparison.' : 'Only the exchange rate changes in this comparison.'}</p></section>\n              <section><h2>What this does not show</h2><p>{limit}</p></section>\n              <p className={wallet.comparison}>Invented research example. Not your account history or live market data.</p>\n              <details><summary>How this is calculated</summary>\n                <p>A made-up example, shown today and 30 days later.</p>\n                <p>The current USD {usdAmount.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 20 })} is applied to both rates. It does not mean you held this amount for 30 days.</p>\n                <p>Both estimates are rounded to two decimals; the difference uses those rounded amounts. Deposits, withdrawals, yield and asset-price changes are excluded, as are fees and spreads. No money has moved.</p>\n              </details>\n            </div>\n          </dialog>\n        </> : result.kind === 'unavailable' ? <p>{result.reason}</p> : null}\n      </section>\n    );\n  }\n\n  return (\n    <section className={styles.context} aria-label=\"Currency context\" data-testid=\"currency-insight\">\n      <div className={styles.heading}>\n        <h2>Currency context</h2>\n        <p>30-day example · Simulated</p>\n      </div>\n      <p className={styles.headline} data-testid=\"currency-insight-headline\">\n        {comparison ? (\n          <span className={styles.direction} aria-hidden=\"true\" data-testid=\"currency-insight-direction\">\n            {comparison.direction === 'higher' ? '↑' : comparison.direction === 'lower' ? '↓' : '—'}\n          </span>\n        ) : null}\n        <span>{headline}</span>\n      </p>\n      {comparison ? (\n        <>\n          <p>Your USD amount is held constant in this comparison.</p>\n          <p className={styles.limit}>FX comparison only—not earnings, purchasing power, guaranteed protection or a conversion quote.</p>\n          <details className={styles.calculation}>\n            <summary>How this is calculated</summary>\n            <div className={styles.explanation}>\n              <p>A made-up example, shown today and 30 days later.</p>\n              <p>The current USD {usdAmount.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 20 })} is applied to both rates. It does not mean you held this amount for 30 days.</p>\n              <dl className={styles.values}>\n                <div>\n                  <dt>Earlier · day 0 <span>1 USD = {comparison.earlierRate.toLocaleString('en-US', { maximumFractionDigits: 20 })} {currency}</span></dt>\n                  <dd>{currency} {formatComparisonCents(comparison.earlierCents)}</dd>\n                </div>\n                <div>\n                  <dt>Latest · day 30 <span>1 USD = {comparison.latestRate.toLocaleString('en-US', { maximumFractionDigits: 20 })} {currency}</span></dt>\n                  <dd>{currency} {formatComparisonCents(comparison.latestCents)}</dd>\n                </div>\n              </dl>\n              <p>Both estimates are rounded to two decimals; the difference uses those rounded amounts. Deposits, withdrawals, yield and asset-price changes are excluded, as are fees and spreads. No money has moved.</p>\n            </div>\n          </details>\n        </>\n      ) : result.kind === 'unavailable' ? <p>{result.reason}</p> : null}\n    </section>\n  );\n}\n",
  "app/(app)/dashboard/EngineStabilityReviewSnapshot.tsx": "\"use client\";\n\nimport React, { useEffect, useMemo, useState } from \"react\";\nimport { formatEngineSnapshotUpdatedAt } from \"../../../lib/engine/format-engine-snapshot-updated-at\";\nimport {\n  REVIEW_SNAPSHOT_FINGERPRINT_STORAGE_KEY,\n  buildReviewSnapshotFingerprint,\n} from \"../../../lib/engine/review-snapshot-fingerprint\";\nimport {\n  appendReviewSnapshotMemoryAfterVisit,\n  readReviewSnapshotMemory,\n  type ReviewSnapshotMemoryEntry,\n} from \"../../../lib/engine/review-snapshot-memory\";\nimport {\n  ENGINE_ILLUSTRATIVE_VALUES_LABEL,\n  ENGINE_STABILITY_REVIEW_AVAILABLE_CONTINUITY,\n  ENGINE_STABILITY_REVIEW_CADENCE_CUE,\n  ENGINE_STABILITY_REVIEW_CHANGE_CHANGED,\n  ENGINE_STABILITY_REVIEW_CHANGE_DISCLAIMER,\n  ENGINE_STABILITY_REVIEW_CHANGE_UNCHANGED,\n  ENGINE_STABILITY_REVIEW_MEMORY_DISCLAIMER,\n  ENGINE_STABILITY_REVIEW_MEMORY_TARGETS_CHANGED,\n  ENGINE_STABILITY_REVIEW_MEMORY_TARGETS_UNCHANGED,\n  ENGINE_STABILITY_REVIEW_MEMORY_TITLE,\n  ENGINE_STABILITY_REVIEW_SNAPSHOT_TITLE,\n  ENGINE_STABILITY_REVIEW_WITHDRAWAL_CONTINUITY,\n  getEngineStabilityReviewSnapshotStance,\n} from \"../../../lib/engine/stability-review-snapshot-copy\";\nimport type { EngineState } from \"../../../lib/engine/types\";\n\ntype EngineStabilityReviewSnapshotProps = {\n  engineState: EngineState;\n};\n\ntype ChangeSignal = \"unchanged\" | \"changed\" | null;\n\nexport function EngineStabilityReviewSnapshot({\n  engineState,\n}: EngineStabilityReviewSnapshotProps) {\n  const fingerprint = useMemo(\n    () => buildReviewSnapshotFingerprint(engineState),\n    [\n      engineState.posture,\n      engineState.liquidityTargetPct,\n      engineState.coreTargetPct,\n      engineState.yieldCapPct,\n    ]\n  );\n\n  const [changeSignal, setChangeSignal] = useState<ChangeSignal>(null);\n  const [memoryEntries, setMemoryEntries] = useState<\n    ReviewSnapshotMemoryEntry[]\n  >([]);\n\n  useEffect(() => {\n    if (typeof window === \"undefined\") {\n      return;\n    }\n    try {\n      const current = fingerprint;\n      const raw = window.localStorage.getItem(\n        REVIEW_SNAPSHOT_FINGERPRINT_STORAGE_KEY\n      );\n      if (raw === null) {\n        window.localStorage.setItem(\n          REVIEW_SNAPSHOT_FINGERPRINT_STORAGE_KEY,\n          current\n        );\n        setChangeSignal(null);\n        setMemoryEntries(readReviewSnapshotMemory());\n        return;\n      }\n      appendReviewSnapshotMemoryAfterVisit({\n        priorFingerprintRaw: raw,\n        currentFingerprint: current,\n        posture: engineState.posture,\n      });\n      setChangeSignal(raw === current ? \"unchanged\" : \"changed\");\n      window.localStorage.setItem(\n        REVIEW_SNAPSHOT_FINGERPRINT_STORAGE_KEY,\n        current\n      );\n      setMemoryEntries(readReviewSnapshotMemory());\n    } catch {\n      setChangeSignal(null);\n      setMemoryEntries(readReviewSnapshotMemory());\n    }\n    // Deps: fingerprint only—encodes posture and targets; avoids duplicate appends on parent object identity churn.\n  }, [fingerprint]);\n\n  return (\n    <section\n      className=\"max-w-2xl rounded-3xl border border-hedgr-200 bg-white p-5 text-sm text-hedgr-dark sm:p-6\"\n      data-testid=\"engine-stability-review-snapshot\"\n      aria-labelledby=\"engine-stability-review-snapshot-title\"\n    >\n      <div>\n        <p className=\"text-xs font-semibold uppercase tracking-[0.12em] text-hedgr-500\">\n          Review\n        </p>\n        <h2\n          id=\"engine-stability-review-snapshot-title\"\n          className=\"mt-1 text-lg font-semibold tracking-tight text-hedgr-800\"\n        >\n          {ENGINE_STABILITY_REVIEW_SNAPSHOT_TITLE}\n        </h2>\n      </div>\n      <div className=\"mt-4\" data-testid=\"engine-stability-review-orientation\">\n        <p className=\"text-xs leading-relaxed text-hedgr-500\">\n          {ENGINE_ILLUSTRATIVE_VALUES_LABEL}\n        </p>\n        <p\n          className=\"mt-1 text-sm font-medium leading-relaxed text-hedgr-800\"\n          data-testid=\"engine-stability-review-snapshot-stance\"\n        >\n          {getEngineStabilityReviewSnapshotStance(engineState.posture)}\n        </p>\n      </div>\n      <dl className=\"mt-4 grid gap-4 border-t border-hedgr-100 pt-4 sm:grid-cols-2\">\n        <div>\n          <dt className=\"text-[11px] font-semibold uppercase tracking-wide text-hedgr-500\">\n            Last viewed locally\n          </dt>\n          <dd\n            className=\"mt-1 text-xs leading-relaxed text-hedgr-600\"\n            data-testid=\"engine-stability-review-last-viewed-locally\"\n          >\n            {memoryEntries[0]\n              ? formatEngineSnapshotUpdatedAt(memoryEntries[0].viewedAt)\n              : \"No prior local view in this browser.\"}\n          </dd>\n        </div>\n      </dl>\n      <details\n        className=\"mt-4 border-t border-hedgr-100 pt-4\"\n        data-testid=\"engine-stability-review-details\"\n      >\n        <summary className=\"cursor-pointer list-none font-medium text-hedgr-800 marker:content-none select-none [&::-webkit-details-marker]:hidden\">\n          <span className=\"flex items-center justify-between gap-4\">\n            <span>Review details</span>\n            <span className=\"text-xs font-medium uppercase tracking-wide text-hedgr-500\">\n              View\n            </span>\n          </span>\n        </summary>\n        <div className=\"mt-4 space-y-3 border-t border-hedgr-100 pt-4\">\n          <p\n            className=\"max-w-xl leading-relaxed text-hedgr-dark\"\n            data-testid=\"engine-stability-review-snapshot-cadence\"\n          >\n            {ENGINE_STABILITY_REVIEW_CADENCE_CUE}\n          </p>\n          {changeSignal !== null && (\n            <p\n              className=\"max-w-xl text-sm font-medium leading-relaxed text-hedgr-600\"\n              data-testid=\"engine-stability-review-snapshot-change-signal\"\n            >\n              {changeSignal === \"unchanged\"\n                ? ENGINE_STABILITY_REVIEW_CHANGE_UNCHANGED\n                : ENGINE_STABILITY_REVIEW_CHANGE_CHANGED}\n            </p>\n          )}\n          <p className=\"max-w-xl leading-relaxed text-hedgr-dark\">\n            {ENGINE_STABILITY_REVIEW_AVAILABLE_CONTINUITY}\n          </p>\n          <p className=\"max-w-xl leading-relaxed text-hedgr-dark\">\n            {ENGINE_STABILITY_REVIEW_WITHDRAWAL_CONTINUITY}\n          </p>\n          {changeSignal !== null && (\n            <p\n              className=\"max-w-xl text-xs leading-relaxed text-hedgr-500\"\n              data-testid=\"engine-stability-review-snapshot-change-disclaimer\"\n            >\n              {ENGINE_STABILITY_REVIEW_CHANGE_DISCLAIMER}\n            </p>\n          )}\n          {memoryEntries.length > 0 && (\n            <div\n              className=\"space-y-3 border-t border-hedgr-100 pt-4\"\n              data-testid=\"engine-stability-review-memory\"\n            >\n              <h3 className=\"text-xs font-medium text-hedgr-800\">\n                {ENGINE_STABILITY_REVIEW_MEMORY_TITLE}\n              </h3>\n              <p className=\"max-w-xl text-xs leading-relaxed text-hedgr-500\">\n                {ENGINE_STABILITY_REVIEW_MEMORY_DISCLAIMER}\n              </p>\n              <div className=\"space-y-4\">\n                {memoryEntries.map((entry, index) => (\n                  <div\n                    key={`${entry.viewedAt}-${index}`}\n                    className=\"space-y-1\"\n                    data-testid=\"engine-stability-review-memory-entry\"\n                  >\n                    <p className=\"text-sm text-hedgr-dark\">\n                      {getEngineStabilityReviewSnapshotStance(entry.posture)}\n                    </p>\n                    <p className=\"text-sm text-hedgr-dark\">\n                      {entry.changeVsPrior === \"unchanged\"\n                        ? ENGINE_STABILITY_REVIEW_MEMORY_TARGETS_UNCHANGED\n                        : ENGINE_STABILITY_REVIEW_MEMORY_TARGETS_CHANGED}\n                    </p>\n                    <p className=\"text-xs text-hedgr-500\">\n                      {formatEngineSnapshotUpdatedAt(entry.viewedAt)}\n                    </p>\n                  </div>\n                ))}\n              </div>\n            </div>\n          )}\n        </div>\n      </details>\n    </section>\n  );\n}\n"
};

